```python
import time
import threading

class TTLCache:
    def __init__(self):
        self.cache = {}
        self.lock = threading.Lock()

    def set(self, key, value, ttl):
        self.cache[key] = (value, time.time() + ttl)

    def get(self, key):
        if key in self.cache:
            val, expiry = self.cache[key]
            if time.time() < expiry:
                return val
            del self.cache[key]
        return None
```
